'use client';

import { useEffect, useRef, useState } from 'react';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import * as THREE from 'three';
import { FishManager, FishConfig } from '@/utils/FishManager';
import { supabase } from '@/lib/supabaseClient';

// Akvaryum Boyutları (main.js içindeki 14, 7, 7)
const TANK_BOUNDS = new THREE.Vector3(14, 7, 7);

// R3F İçinde Balık Simülasyonunu Çalıştıran Ve Güncelleyen İç Bileşen
function FishEngineController({
  fishCount,
  fishConfigs,
}: {
  fishCount: number;
  fishConfigs: FishConfig[];
}) {
  const { scene } = useThree();
  const fishManagerRef = useRef<FishManager | null>(null);

  // Balık Motorunu Başlat
  useEffect(() => {
    if (fishConfigs.length > 0 && !fishManagerRef.current) {
      fishManagerRef.current = new FishManager(scene, TANK_BOUNDS, fishCount, fishConfigs);
    }
  }, [scene, fishConfigs]);

  // Slider ile balık sayısı değiştiğinde tetiklenir
  useEffect(() => {
    if (fishManagerRef.current) {
      fishManagerRef.current.setFishCount(fishCount);
    }
  }, [fishCount]);

  // Her render karesinde (requestAnimationFrame yerine) çalışır
  useFrame((state) => {
    if (fishManagerRef.current) {
      fishManagerRef.current.update(state.clock.getElapsedTime());
    }
  });

  return null;
}

// Akvaryum Cam Çerçevesi (main.js -> initGlassBounds)
function GlassBounds() {
  return (
    <lineSegments position={[0, 0, 0]}>
      <edgesGeometry args={[new THREE.BoxGeometry(TANK_BOUNDS.x, TANK_BOUNDS.y, TANK_BOUNDS.z)]} />
      <lineBasicMaterial color="#38bdf8" transparent opacity={0.35} />
    </lineSegments>
  );
}

export default function AquariumScene() {
  const [dbStatus, setDbStatus] = useState<string>('Bağlanıyor...');
  const [fishCount, setFishCount] = useState<number>(20);
  const [fishConfigs, setFishConfigs] = useState<FishConfig[]>([]);

  // 1. Supabase Bağlantı Testi
  useEffect(() => {
    async function checkConnection() {
      const { error } = await supabase.from('_test_connection').select('*').limit(1);
      if (!error || error.code === 'PGRST116' || error.code === '42P01') {
        setDbStatus('Supabase Bağlantısı Başarılı!');
      } else {
        setDbStatus('Bağlantı Hatası');
      }
    }
    checkConnection();
  }, []);

  // 2. fishConfig.json Yükleme
  useEffect(() => {
    async function loadConfigs() {
      try {
        const res = await fetch('/data/fishConfig.json');
        if (res.ok) {
          const data = await res.json();
          setFishConfigs(data);
        }
      } catch (err) {
        console.error('Konfigürasyon dosyası yüklenemedi:', err);
      }
    }
    loadConfigs();
  }, []);

  return (
    <div className="w-full h-screen relative bg-slate-900 select-none">
      {/* Sol Üst: Supabase Durumu */}
      <div className="absolute top-4 left-4 z-10 bg-slate-800/90 text-white px-4 py-2 rounded-lg border border-slate-700 text-sm shadow-lg backdrop-blur">
        Supabase: <span className="text-emerald-400 font-semibold">{dbStatus}</span>
      </div>

      {/* Sağ Üst: Balık Sayısı Slider UI */}
      <div className="absolute top-4 right-4 z-10 bg-slate-800/90 text-white p-4 rounded-xl border border-slate-700 shadow-xl backdrop-blur flex flex-col gap-2 min-w-[200px]">
        <div className="flex justify-between items-center text-sm font-medium">
          <span>Balık Sayısı</span>
          <span className="text-cyan-400 font-bold">{fishCount}</span>
        </div>
        <input
          type="range"
          min="1"
          max="100"
          value={fishCount}
          onChange={(e) => setFishCount(parseInt(e.target.value, 10))}
          className="w-full accent-cyan-400 cursor-pointer"
        />
      </div>

      {/* 3D Canvas Sahnesi */}
      <Canvas
        camera={{ position: [0, 2, 13], fov: 50 }}
        onCreated={({ scene }) => {
          // Su altı sisi ve arkaplan rengi (main.js ile birebir)
          scene.background = new THREE.Color(0x04192b);
          scene.fog = new THREE.FogExp2(0x04192b, 0.045);
        }}
      >
        {/* Işıklandırma (main.js ile birebir) */}
        <directionalLight position={[0, 8, 2]} intensity={2.2} color="#dcf4ff" />
        <ambientLight intensity={1.4} color="#0a3c59" />

        {/* Cam Çerçeve */}
        <GlassBounds />

        {/* Balık Simülasyon Motoru */}
        <FishEngineController fishCount={fishCount} fishConfigs={fishConfigs} />

        {/* Kamera Kontrolleri */}
        <OrbitControls makeDefault enableDamping dampingFactor={0.05} />
      </Canvas>
    </div>
  );
}